export default async function () {
  const conns = await client.connections.list();
  const stray = conns.connections.filter(c =>
    (c.slug || '').includes('mcp-e2e') || (c.display_name || '').includes('mcp-e2e'));
  const behaviors = await client.behaviors.list({ limit: 200 });
  const strayB = (behaviors.behaviors || []).filter(b =>
    (b.slug || '').includes('mcp-e2e'));
  const feeds = await client.feeds.list({ limit: 200 });
  const strayF = (feeds.feeds || []).filter(f =>
    (f.name || '').includes('mcp-e2e') || (f.slug || '').includes('mcp-e2e'));
  return {
    stray_connections: stray.map(c => ({ id: c.id, slug: c.slug, status: c.status })),
    stray_behaviors: strayB.map(b => ({ id: b.behavior_id || b.id, slug: b.slug, status: b.status })),
    stray_feeds: strayF.map(f => ({ id: f.id, name: f.name, status: f.status })),
    totals: { conns: conns.total, behaviors: (behaviors.behaviors||[]).length, feeds: (feeds.feeds||[]).length }
  };
}

