export default async function () {
  const out = {};
  for (const cid of [347, 342, 232, 387]) {
    const f = await client.feeds.list({ connection_id: cid, limit: 100 });
    const feeds = (f.feeds || []).map(x => ({
      id: x.id, status: x.status, cf: x.consecutive_failures,
      last_status: x.last_sync_status, last_sync: x.last_sync_at
    }));
    const feedCount = feeds.length;
    const failing = feeds.filter(x => x.last_status === 'failed' || (x.cf || 0) >= 3).length;
    const activeCount = feeds.filter(x => !(x.status === 'paused' && (x.cf || 0) === 0)).length;
    const successSyncs = feeds.filter(x => x.last_status === 'success' && x.last_sync).map(x => x.last_sync).sort();
    out[cid] = {
      feedCount, failing, activeCount,
      newest_success: successSyncs[successSyncs.length - 1] || null,
      rule_zero_feeds: feedCount === 0,
      rule_all_failing: failing === feedCount && feedCount > 0,
      feeds
    };
  }
  return out;
}

